import sys
from collections import defaultdict

def solve():
    # Read all tokens from standard input for fast I/O
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    T = int(input_data[0])
    idx = 1
    out = []

    for _ in range(T):
        N = int(input_data[idx])
        idx += 1
        L = 2 * N

        # Parse array A
        A = [int(x) for x in input_data[idx : idx+L]]
        idx += L

        # Record all positions where an adjacent pair of distinct elements occurs
        # Key: tuple(min(x, y), max(x, y)), Value: list of starting indices
        groups = defaultdict(list)
        for i in range(L - 1):
            x = A[i]
            y = A[i+1]
            if x != y:
                if x < y:
                    groups[(x, y)].append(i)
                else:
                    groups[(y, x)].append(i)

        ans = 0
        for lst in groups.values():
            k = len(lst)
            # We need the pair {a, b} to appear as adjacent at least twice
            if k < 2:
                continue

            # Check all pairs of adjacencies for the current tuple (a, b)
            for a_idx in range(k):
                ia = lst[a_idx]
                for b_idx in range(a_idx + 1, k):
                    jb = lst[b_idx]
                    d = jb - ia

                    if d == 1:
                        # Overlapping adjacencies by 1 element (e.g., a, b, a)
                        # The 4th element is disconnected, cannot be partitioned into two valid adjacent pairs
                        continue
                    elif d == 2:
                        # Adjacencies are offset by 2 (e.g., spanning 4 consecutive elements)
                        # We must ensure they form an alternating pattern like a, b, a, b
                        # rather than a mirrored pattern like a, b, b, a (where an element is originally adjacent to itself, which violates conditions)
                        if A[ia] == A[jb]:
                            ans += 1
                    else:
                        # d >= 3: The two pairs of adjacencies are completely disjoint.
                        # Since each element appears exactly twice in the entire array, 
                        # they cannot be adjacent to themselves anywhere else, making this configuration unconditionally valid.
                        ans += 1

        out.append(str(ans))

    sys.stdout.write('\n'.join(out) + '\n')

if __name__ == '__main__':
    solve()
